    private static readonly ResourceManager ResourceManager = new("Sidekick.Localization.Strings", typeof(Strings).Assembly);

    // Only Sidekick's resource culture changes; never change the shared framework thread's culture.
    internal static CultureInfo Culture { get; set; } = LanguagePreference.CultureFor(LanguagePreference.DefaultCode);

    private static string Get(string name) => ResourceManager.GetString(name, Culture)
        ?? ResourceManager.GetString(name, CultureInfo.InvariantCulture)
        ?? throw new MissingManifestResourceException($"Missing resource: {name}");

